sqlEquivalent:
CREATE TABLE lab_customers (id SERIAL PRIMARY KEY, email VARCHAR(200) UNIQUE NOT NULL);
CREATE TABLE lab_orders (
  id SERIAL PRIMARY KEY,
  total NUMERIC(10,2) NOT NULL,
  customer_id INTEGER NOT NULL REFERENCES lab_customers(id)
);

starterCode:
model LabCustomer {
  id Int @id @default(autoincrement())
  email String @unique
  orders LabOrder[]
  @@map("lab_customers")
}
model LabOrder {
  id Int @id @default(autoincrement())
  total Decimal @db.Decimal(10, 2)
  customerId Int @map("customer_id")
  customer LabCustomer @relation(fields: [customerId], references: [id])
  @@map("lab_orders")
}

